//! ProtoJSON, as Temporal's CLI, Web UI and codec servers write it, for the generated
//! protobuf message types: `encode` and `decode`.

const std = @import("std");
const protobuf = @import("protobuf");
const Allocator = std.mem.Allocator;

pub const DecodeError = error{ OutOfMemory, InvalidProtoJson };

/// Encodes a generated protobuf message as ProtoJSON, as Temporal's CLI, Web UI and codec
/// servers read it. `message` is a value of a type generated by zig-protobuf (the SDK's own
/// under `temporal.proto`, or one generated for an application); any other type is a compile
/// error.
///
/// The output is minified standard ProtoJSON: lowerCamelCase field names with the fields of
/// a oneof written flat, bytes fields and the values of `map<string, bytes>` fields as
/// standard padded base64, 64-bit integers as strings, and fields at their default left out.
/// Enum values are written by their full name (`EVENT_TYPE_WORKFLOW_EXECUTION_STARTED`), which
/// every Temporal tool reads; a number the generated enum does not name is written as that
/// number.
///
/// The text is allocated with `arena`; the message is only read. `decode` reads it back to an
/// equal message, except for messages inside a `google.protobuf.Any`. Messages nested more
/// than 256 JSON objects and arrays deep are beyond `std.json.Stringify`'s limit; no message
/// `decode` or the binary decoder returns nests that deep (both stop at 100 messages).
pub fn encode(arena: Allocator, message: anytype) error{OutOfMemory}![]u8 {
    const T = @TypeOf(message);
    if (comptime !isMessage(T))
        @compileError("protojson.encode takes a message type generated by zig-protobuf, not " ++ @typeName(T));
    return protobuf.json.encode(message, .{}, .{ .emit_oneof_field_name = false }, arena) catch |err| switch (err) {
        error.OutOfMemory => return error.OutOfMemory,
    };
}

/// Decodes ProtoJSON, as Temporal's CLI, Web UI and codec servers write it, into the
/// generated message type `T`.
///
/// Field names may be lowerCamelCase or as in the .proto file, and the fields of a oneof flat
/// or (with no short enum names inside) wrapped in the oneof's name. Bytes fields and the
/// values of `map<string, bytes>` fields are base64, standard or URL-safe, padded or not. An
/// enum value may be its full name (`EVENT_TYPE_WORKFLOW_EXECUTION_STARTED`), its number, or
/// the short name older CLI and Web UI exports write (`WorkflowExecutionStarted`, `Normal`):
/// the value's full name without the enum's prefix, compared without underscores and case.
/// A full name always wins over a short one.
///
/// Unknown input is not an error: fields `T` does not know are skipped, and an enum name that
/// matches no value decodes as the enum's zero value in a singular field and is dropped from
/// a repeated field or a map. Messages inside a
/// `google.protobuf.Any` are left as the generated decoder returns them: their short enum
/// names are not rewritten and their bytes-map values are not decoded.
///
/// `error.InvalidProtoJson` is everything else: text that is not JSON, a value of the wrong
/// JSON type for its field, invalid base64, a number out of range, and, for a `T` that can
/// hold an enum (whose text is rewritten through `std.json.Stringify`), text nested deeper
/// than 256 objects and arrays.
///
/// The result lives entirely in `arena` and borrows nothing from `json`. Nothing is freed
/// piecewise, so pass an arena. Pure and deterministic; safe from any thread.
pub fn decode(comptime T: type, arena: Allocator, json: []const u8) DecodeError!T {
    if (comptime !isMessage(T))
        @compileError("protojson.decode takes a message type generated by zig-protobuf, not " ++ @typeName(T));
    // Short enum names must be rewritten before the generated decoder runs: with
    // `ignore_unknown_fields` it turns a name it doesn't know into 0 without an error.
    const text = if (comptime mayHoldEnum(T)) try rewriteShortEnumNames(T, arena, json) else json;
    var witness: FailureWitness = .{ .child = arena };
    const parsed = T.jsonDecode(text, .{
        .ignore_unknown_fields = true,
        .allocate = .alloc_always,
    }, witness.allocator()) catch |err| switch (err) {
        error.OutOfMemory => return error.OutOfMemory,
        // The generated decoder reports a failed allocation of a bytes value as a syntax
        // error (zig-protobuf's `parse_bytes` catches it): after a failed allocation, an
        // error is the allocation's.
        else => return if (witness.failed) error.OutOfMemory else error.InvalidProtoJson,
    };
    var message = parsed.value;
    try decodeBytesMaps(T, &message, arena);
    return message;
}

/// Passes allocations through to `child` and records whether one failed.
const FailureWitness = struct {
    child: Allocator,
    failed: bool = false,

    fn allocator(w: *FailureWitness) Allocator {
        return .{ .ptr = w, .vtable = &.{ .alloc = alloc, .resize = resize, .remap = remap, .free = free } };
    }

    fn alloc(ctx: *anyopaque, len: usize, alignment: std.mem.Alignment, ret_addr: usize) ?[*]u8 {
        const w: *FailureWitness = @ptrCast(@alignCast(ctx));
        const memory = w.child.rawAlloc(len, alignment, ret_addr);
        if (memory == null) w.failed = true;
        return memory;
    }

    // A refused resize or remap is not a failure: the caller allocates anew, and that
    // allocation is recorded if it fails.
    fn resize(ctx: *anyopaque, memory: []u8, alignment: std.mem.Alignment, new_len: usize, ret_addr: usize) bool {
        const w: *FailureWitness = @ptrCast(@alignCast(ctx));
        return w.child.rawResize(memory, alignment, new_len, ret_addr);
    }

    fn remap(ctx: *anyopaque, memory: []u8, alignment: std.mem.Alignment, new_len: usize, ret_addr: usize) ?[*]u8 {
        const w: *FailureWitness = @ptrCast(@alignCast(ctx));
        return w.child.rawRemap(memory, alignment, new_len, ret_addr);
    }

    fn free(ctx: *anyopaque, memory: []u8, alignment: std.mem.Alignment, ret_addr: usize) void {
        const w: *FailureWitness = @ptrCast(@alignCast(ctx));
        w.child.rawFree(memory, alignment, ret_addr);
    }
};

fn isMessage(comptime T: type) bool {
    return @typeInfo(T) == .@"struct" and @hasDecl(T, "_desc_table") and std.meta.hasFn(T, "jsonDecode");
}

/// How deeply the JSON text may nest objects and arrays: `std.json.Stringify`, which writes
/// the rewritten tree back, asserts this limit.
const max_json_depth = 256;

/// Parses `json` into a tree, rewrites the short enum names in it to full names guided by
/// `T`, and writes it back to text in `arena`.
fn rewriteShortEnumNames(comptime T: type, arena: Allocator, json: []const u8) DecodeError![]const u8 {
    // Numbers stay as written, so the generated decoder sees the same text.
    var root = std.json.parseFromSliceLeaky(std.json.Value, arena, json, .{ .parse_numbers = false }) catch |err| switch (err) {
        error.OutOfMemory => return error.OutOfMemory,
        else => return error.InvalidProtoJson,
    };
    if (!withinDepth(root, 1)) return error.InvalidProtoJson;
    fixMessage(T, &root);
    return std.json.Stringify.valueAlloc(arena, root, .{});
}

/// Whether `v`, found at nesting `depth`, nests no deeper than `max_json_depth`. Recurses at
/// most `max_json_depth` times.
fn withinDepth(v: std.json.Value, depth: usize) bool {
    switch (v) {
        .array => |array| {
            if (depth > max_json_depth) return false;
            for (array.items) |item| if (!withinDepth(item, depth + 1)) return false;
        },
        .object => |object| {
            if (depth > max_json_depth) return false;
            for (object.values()) |item| if (!withinDepth(item, depth + 1)) return false;
        },
        else => {},
    }
    return true;
}

/// Rewrites the short enum names in `v`, the JSON object of a message `M`. Fields are
/// reached as `fieldKind` reads their descriptors; values of the wrong JSON type are left
/// for the generated decoder to reject.
fn fixMessage(comptime M: type, v: *std.json.Value) void {
    @setEvalBranchQuota(1_000_000);
    if (comptime !mayHoldEnum(M)) return;
    if (v.* != .object) return;
    inline for (@typeInfo(M).@"struct".field_names) |name| {
        if (comptime !@hasField(@TypeOf(M._desc_table), name)) continue;
        switch (comptime fieldKind(M, name)) {
            .skip => {},
            .singular => |F| if (fieldValue(v, name)) |child| fixValue(F, child),
            .list => |E| if (fieldValue(v, name)) |child| {
                if (child.* == .array) for (child.array.items) |*item| fixValue(E, item);
            },
            .map => |Entry| if (fieldValue(v, name)) |child| {
                if (child.* == .object) for (child.object.values()) |*item| fixValue(@FieldType(Entry, "value"), item);
            },
            // Standard ProtoJSON writes a oneof's members flat, in the parent object.
            .oneof => |U| inline for (@typeInfo(U).@"union".field_names, @typeInfo(U).@"union".field_types) |member, F| {
                if (fieldValue(v, member)) |child| fixValue(F, child);
            },
        }
    }
}

/// Rewrites a short enum name in `v`, a single value of type `F`: an enum, or a message.
fn fixValue(comptime F: type, v: *std.json.Value) void {
    const S = Singular(F);
    if (comptime @typeInfo(S) == .@"enum") {
        fixEnum(S, v);
    } else if (comptime isWalkedMessage(S)) {
        fixMessage(S, v);
    }
}

fn fieldValue(v: *std.json.Value, comptime name: []const u8) ?*std.json.Value {
    return v.object.getPtr(comptime camel(name)) orelse v.object.getPtr(name);
}

/// Replaces a short enum name in `v` with the full name it matches. A full name, in any case
/// (which the generated decoder accepts), a number, and a name that matches nothing are left
/// alone.
fn fixEnum(comptime E: type, v: *std.json.Value) void {
    if (v.* != .string) return;
    const s = v.string;
    const names = @typeInfo(E).@"enum".field_names;
    inline for (names) |tag| if (std.ascii.eqlIgnoreCase(tag, s)) return;
    const prefix = comptime enumPrefix(E);
    if (prefix.len == 0) return;
    inline for (names) |tag| {
        if (comptime std.mem.startsWith(u8, tag, prefix) and tag.len > prefix.len) {
            if (eqlShort(tag[prefix.len..], s)) {
                v.* = .{ .string = tag };
                return;
            }
        }
    }
}

/// Whether `full` (a SCREAMING_SNAKE_CASE name without its prefix) equals `short` once both
/// drop their underscores and case is ignored.
fn eqlShort(full: []const u8, short: []const u8) bool {
    var i: usize = 0;
    var j: usize = 0;
    while (true) {
        while (i < full.len and full[i] == '_') i += 1;
        while (j < short.len and short[j] == '_') j += 1;
        if (i == full.len or j == short.len) return i == full.len and j == short.len;
        if (std.ascii.toLower(full[i]) != std.ascii.toLower(short[j])) return false;
        i += 1;
        j += 1;
    }
}

/// "EVENT_TYPE_" for an enum whose first value is EVENT_TYPE_UNSPECIFIED; empty, so no short
/// names, for an enum whose first value doesn't end in UNSPECIFIED.
fn enumPrefix(comptime E: type) []const u8 {
    const names = @typeInfo(E).@"enum".field_names;
    if (names.len == 0) return "";
    const first = names[0];
    const suffix = "UNSPECIFIED";
    if (std.mem.endsWith(u8, first, suffix)) return first[0 .. first.len - suffix.len];
    return "";
}

fn camel(comptime name: []const u8) []const u8 {
    comptime {
        var out: []const u8 = "";
        var upper = false;
        for (name) |ch| {
            if (ch == '_') {
                upper = true;
                continue;
            }
            out = out ++ &[_]u8{if (upper) std.ascii.toUpper(ch) else ch};
            upper = false;
        }
        return out;
    }
}

/// How zig-protobuf's `json.zig` reads a field, decided as it decides it: by the field's
/// descriptor, never by the shape of the field's type. A value is a map entry only as an
/// element of a repeated field whose element type has exactly the fields `key` and `value`;
/// a message with those two fields anywhere else (a singular field, a oneof member, the
/// top-level message) is an ordinary message.
const FieldKind = union(enum) {
    /// A scalar, string or bytes field, which the generated decoder reads completely.
    skip,
    /// A single enum or message, possibly optional or behind a pointer.
    singular: type,
    /// A repeated field of this element type.
    list: type,
    /// A map field with this entry type.
    map: type,
    /// A oneof with this union type.
    oneof: type,
};

fn fieldKind(comptime M: type, comptime name: []const u8) FieldKind {
    const F = @FieldType(M, name);
    return switch (@field(M._desc_table, name).ftype) {
        .scalar => .skip,
        .@"enum", .submessage => .{ .singular = F },
        .repeated, .packed_repeated => blk: {
            const Elem = @typeInfo(@FieldType(F, "items")).pointer.child;
            break :blk if (isMapEntry(Elem)) .{ .map = Elem } else .{ .list = Elem };
        },
        .oneof => .{ .oneof = Singular(F) },
    };
}

/// `F` without its optional and single-item pointer wrappers.
fn Singular(comptime F: type) type {
    return switch (@typeInfo(F)) {
        .optional => |o| Singular(o.child),
        .pointer => |p| if (p.size == .one) Singular(p.child) else F,
        else => F,
    };
}

/// A generated message whose JSON form is the object of its fields. The well-known types
/// zig-protobuf defines in `protobuf.wkt` (`Timestamp`, `Duration`, `Any`, `Struct`, the
/// wrappers and others) read and write their own JSON forms, so neither walk enters them.
fn isWalkedMessage(comptime T: type) bool {
    return @typeInfo(T) == .@"struct" and @hasDecl(T, "_desc_table") and !isWellKnown(T);
}

fn isWellKnown(comptime T: type) bool {
    comptime {
        for (@typeInfo(protobuf.wkt).@"struct".decl_names) |name| {
            if (@TypeOf(@field(protobuf.wkt, name)) == type and @field(protobuf.wkt, name) == T) return true;
        }
        return false;
    }
}

/// The element shape zig-protobuf's `json.zig` reads a repeated field as a JSON object by.
fn isMapEntry(comptime T: type) bool {
    if (@typeInfo(T) != .@"struct") return false;
    const names = @typeInfo(T).@"struct".field_names;
    return names.len == 2 and std.mem.eql(u8, names[0], "key") and std.mem.eql(u8, names[1], "value");
}

/// A map entry, by `fieldKind`, whose value is bytes by its descriptor.
fn isBytesMapEntry(comptime Entry: type) bool {
    if (!@hasDecl(Entry, "_desc_table")) return false;
    return switch (Entry._desc_table.value.ftype) {
        .scalar => |s| s == .bytes,
        else => false,
    };
}

const Want = enum { enum_value, bytes_map };

/// Whether a message `M` can reach an enum value.
fn mayHoldEnum(comptime M: type) bool {
    comptime {
        @setEvalBranchQuota(1_000_000);
        var seen: []const type = &.{};
        return messageReaches(M, .enum_value, &seen);
    }
}

/// Whether a message `M` can reach a `map<string, bytes>` field.
fn mayHoldBytesMap(comptime M: type) bool {
    comptime {
        @setEvalBranchQuota(1_000_000);
        var seen: []const type = &.{};
        return messageReaches(M, .bytes_map, &seen);
    }
}

/// Whether the walks, which reach fields as `fieldKind` reads them, can find what `want`
/// names in a message `M`: a depth-first search over message types. Generated messages refer
/// to themselves through pointers (a failure's `cause`) and through lists and map values (a
/// descriptor's `nested_type`), so each type is searched once: a type already in `seen` was
/// either found to reach none or is still being searched further up, and either way adds
/// nothing.
fn messageReaches(comptime M: type, comptime want: Want, comptime seen: *[]const type) bool {
    if (!isWalkedMessage(M)) return false;
    for (seen.*) |S| if (S == M) return false;
    seen.* = seen.* ++ .{M};
    for (@typeInfo(M).@"struct".field_names) |name| {
        if (!@hasField(@TypeOf(M._desc_table), name)) continue;
        const found = switch (fieldKind(M, name)) {
            .skip => false,
            .singular, .list => |F| valueReaches(F, want, seen),
            .map => |Entry| (want == .bytes_map and isBytesMapEntry(Entry)) or
                valueReaches(@FieldType(Entry, "value"), want, seen),
            .oneof => |U| for (@typeInfo(U).@"union".field_types) |F| {
                if (valueReaches(F, want, seen)) break true;
            } else false,
        };
        if (found) return true;
    }
    return false;
}

fn valueReaches(comptime F: type, comptime want: Want, comptime seen: *[]const type) bool {
    const S = Singular(F);
    if (@typeInfo(S) == .@"enum") return want == .enum_value;
    return messageReaches(S, want, seen);
}

/// Replaces every value of every `map<string, bytes>` field reachable from `message` with
/// its base64-decoded bytes. Fields are reached as `fieldKind` reads their descriptors, the
/// way the generated decoder read them, so exactly the values it left as base64 text are
/// decoded, each once; every other bytes value, including the `value` of a message that has
/// only `key` and `value` fields, was decoded by the generated decoder and is not touched.
/// The values all live in `arena` (the generated decoder put them there), so they are
/// changed in place.
///
/// This works around a defect of zig-protobuf: its `json.zig` parses map values with
/// `std.json.innerParse`, which treats a bytes value as a plain string, so the base64 text is
/// never decoded. Delete this walk once the pinned zig-protobuf commit decodes them; the
/// round-trip test "a Payload's metadata decodes from base64 and encodes back" then fails by
/// decoding twice.
fn decodeBytesMaps(comptime M: type, message: *M, arena: Allocator) DecodeError!void {
    if (comptime !mayHoldBytesMap(M)) return;
    inline for (@typeInfo(M).@"struct".field_names) |name| {
        if (comptime !@hasField(@TypeOf(M._desc_table), name)) continue;
        const field = &@field(message, name);
        switch (comptime fieldKind(M, name)) {
            .skip => {},
            .singular => |F| try decodeValueBytesMaps(F, field, arena),
            .list => |E| for (field.items) |*item| try decodeValueBytesMaps(E, item, arena),
            .map => |Entry| for (field.items) |*entry| {
                if (comptime isBytesMapEntry(Entry)) {
                    entry.value = protobuf.json.decodeBase64Lenient(arena, entry.value) catch |err| switch (err) {
                        error.OutOfMemory => return error.OutOfMemory,
                        else => return error.InvalidProtoJson,
                    };
                } else {
                    try decodeValueBytesMaps(@FieldType(Entry, "value"), &entry.value, arena);
                }
            },
            .oneof => try decodeValueBytesMaps(@FieldType(M, name), field, arena),
        }
    }
}

/// `decodeBytesMaps` for a single value of type `F`: a message, possibly optional or behind
/// a pointer, or the union of a oneof.
fn decodeValueBytesMaps(comptime F: type, value: *F, arena: Allocator) DecodeError!void {
    switch (@typeInfo(F)) {
        .optional => |o| if (value.*) |*inner| try decodeValueBytesMaps(o.child, inner, arena),
        .pointer => |p| if (p.size == .one) try decodeValueBytesMaps(p.child, value.*, arena),
        .@"union" => switch (value.*) {
            inline else => |*member| try decodeValueBytesMaps(@TypeOf(member.*), member, arena),
        },
        .@"struct" => if (comptime isWalkedMessage(F)) try decodeBytesMaps(F, value, arena),
        else => {},
    }
}

// ---------------------------------------------------------------- tests

const testing = std.testing;
const proto = @import("proto.zig");
const common = proto.temporal.api.common.v1;

test "a Payload's metadata decodes from base64 and encodes back" {
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const json =
        \\{"metadata":{"encoding":"anNvbi9wbGFpbg=="},"data":"IlRlbXBvcmFsIg=="}
    ;
    const p = try decode(common.Payload, a, json);
    try testing.expectEqual(@as(usize, 1), p.metadata.items.len);
    try testing.expectEqualStrings("encoding", p.metadata.items[0].key);
    try testing.expectEqualStrings("json/plain", p.metadata.items[0].value);
    try testing.expectEqualStrings("\"Temporal\"", p.data);
    try testing.expectEqualStrings(json, try encode(a, p));
}

test "metadata values that are not UTF-8 and URL-safe unpadded base64 decode" {
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    // 0xff 0xfe 0xfd is "//79" in standard base64 and "__79" URL-safe; "_-8" is 0xff 0xef.
    const p = try decode(common.Payload, a,
        \\{"metadata":{"raw":"//79","url":"_-8"}}
    );
    try testing.expectEqual(@as(usize, 2), p.metadata.items.len);
    try testing.expectEqualSlices(u8, &.{ 0xff, 0xfe, 0xfd }, p.metadata.items[0].value);
    try testing.expectEqualSlices(u8, &.{ 0xff, 0xef }, p.metadata.items[1].value);
    try testing.expectEqualStrings(
        \\{"metadata":{"raw":"//79","url":"/+8="}}
    , try encode(a, p));
}

test "invalid base64 in a metadata value is InvalidProtoJson" {
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    try testing.expectError(error.InvalidProtoJson, decode(common.Payload, arena.allocator(),
        \\{"metadata":{"encoding":"not base64!"}}
    ));
    try testing.expectError(error.InvalidProtoJson, decode(common.Payload, arena.allocator(), "{"));
}

test "payloads in repeated fields, map values and oneofs of nested messages decode" {
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();

    // Repeated: Payloads.payloads.
    const ps = try decode(common.Payloads, a,
        \\{"payloads":[{"metadata":{"encoding":"anNvbi9wbGFpbg=="},"data":"MQ=="},{"metadata":{"encoding":"YmluYXJ5L251bGw="}}]}
    );
    try testing.expectEqual(@as(usize, 2), ps.payloads.items.len);
    try testing.expectEqualStrings("json/plain", ps.payloads.items[0].metadata.items[0].value);
    try testing.expectEqualStrings("binary/null", ps.payloads.items[1].metadata.items[0].value);

    // Map values that are messages: Memo.fields.
    const memo = try decode(common.Memo, a,
        \\{"fields":{"note":{"metadata":{"encoding":"anNvbi9wbGFpbg=="},"data":"ImhpIg=="}}}
    );
    try testing.expectEqualStrings("json/plain", memo.fields.items[0].value.?.metadata.items[0].value);
    try testing.expectEqualStrings("\"hi\"", memo.fields.items[0].value.?.data);

    // A oneof member, an optional submessage, and a pointer-held submessage: Failure's
    // failure_info, encoded_attributes and cause.
    const f = try decode(proto.temporal.api.failure.v1.Failure, a,
        \\{"message":"outer","encodedAttributes":{"metadata":{"encoding":"anNvbi9wbGFpbg=="}},
        \\ "cause":{"message":"inner","cause":{"applicationFailureInfo":{"details":{"payloads":[{"metadata":{"encoding":"YmluYXJ5L251bGw="}}]}}}}}
    );
    try testing.expectEqualStrings("json/plain", f.encoded_attributes.?.metadata.items[0].value);
    const inner = f.cause.?.cause.?;
    const details = inner.failure_info.?.application_failure_info.details.?;
    try testing.expectEqualStrings("binary/null", details.payloads.items[0].metadata.items[0].value);
}

test "the result borrows nothing from the input" {
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    const json = try testing.allocator.dupe(u8,
        \\{"payloads":[{"metadata":{"encoding":"anNvbi9wbGFpbg=="},"data":"MQ=="}]}
    );
    const ps = decode(common.Payloads, arena.allocator(), json);
    @memset(json, 'x');
    testing.allocator.free(json);
    const p = (try ps).payloads.items[0];
    try testing.expectEqualStrings("encoding", p.metadata.items[0].key);
    try testing.expectEqualStrings("json/plain", p.metadata.items[0].value);
}

test "a message that holds a repeated field of its own type decodes" {
    // google.protobuf.DescriptorProto.nested_type is `repeated DescriptorProto`: the walk's
    // compile-time pruning must end on a type that refers to itself through a list, not only
    // through a pointer.
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    const d = try decode(proto.google.protobuf.DescriptorProto, arena.allocator(),
        \\{"name":"Outer","nestedType":[{"name":"Inner"}]}
    );
    try testing.expectEqualStrings("Outer", d.name.?);
    try testing.expectEqualStrings("Inner", d.nested_type.items[0].name.?);
}

test "encode writes standard ProtoJSON with full enum names and numbers for unnamed values" {
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const history = proto.temporal.api.history.v1;
    const enums = proto.temporal.api.enums.v1;
    const event: history.HistoryEvent = .{
        .event_id = 1,
        .event_type = .EVENT_TYPE_WORKFLOW_EXECUTION_STARTED,
        .attributes = .{ .workflow_execution_started_event_attributes = .{
            .workflow_type = .{ .name = "W" },
            .task_queue = .{ .name = "q", .kind = @fromBackingInt(@intCast(99)) },
        } },
    };
    try testing.expectEqualStrings(
        \\{"eventId":"1","eventType":"EVENT_TYPE_WORKFLOW_EXECUTION_STARTED","workflowExecutionStartedEventAttributes":{"workflowType":{"name":"W"},"taskQueue":{"name":"q","kind":99}}}
    , try encode(a, event));
    const back = try decode(history.HistoryEvent, a, try encode(a, event));
    try testing.expectEqual(@as(enums.TaskQueueKind, @fromBackingInt(@intCast(99))), back.attributes.?.workflow_execution_started_event_attributes.task_queue.?.kind);
}

test "a Payload with binary data and metadata that is not UTF-8 round-trips" {
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    var p: common.Payload = .{ .data = &.{ 0x00, 0xff, 0xc3, 0x28, 0x80 } };
    try p.metadata.append(a, .{ .key = "encoding", .value = "binary/plain" });
    try p.metadata.append(a, .{ .key = "iv", .value = &.{ 0xc3, 0x28, 0xff, 0x00 } });
    const json = try encode(a, p);
    try testing.expectEqualStrings(
        \\{"metadata":{"encoding":"YmluYXJ5L3BsYWlu","iv":"wyj/AA=="},"data":"AP/DKIA="}
    , json);
    const back = try decode(common.Payload, a, json);
    try testing.expectEqualSlices(u8, p.data, back.data);
    try testing.expectEqual(@as(usize, 2), back.metadata.items.len);
    for (p.metadata.items, back.metadata.items) |want, got| {
        try testing.expectEqualStrings(want.key, got.key);
        try testing.expectEqualSlices(u8, want.value, got.value);
    }
    try testing.expectEqualStrings(json, try encode(a, back));
}

test "a Payloads list as a codec server answers it decodes" {
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    // As a codec server written with another toolkit answers: pretty-printed, proto field
    // names, an unknown field, and bytes as URL-safe base64 without padding.
    const ps = try decode(common.Payloads, arena.allocator(),
        \\{
        \\  "payloads": [
        \\    {"metadata": {"encoding": "YmluYXJ5L3NuYXBweQ", "raw": "__79"}, "data": "AP-A"},
        \\    {"metadata": {"encoding": "anNvbi9wbGFpbg=="}, "data": "NDI=", "external_payloads": [], "extra": {"x": [1, 2]}}
        \\  ]
        \\}
    );
    try testing.expectEqual(@as(usize, 2), ps.payloads.items.len);
    const first = ps.payloads.items[0];
    try testing.expectEqualStrings("binary/snappy", first.metadata.items[0].value);
    try testing.expectEqualSlices(u8, &.{ 0xff, 0xfe, 0xfd }, first.metadata.items[1].value);
    try testing.expectEqualSlices(u8, &.{ 0x00, 0xff, 0x80 }, first.data);
    try testing.expectEqualStrings("json/plain", ps.payloads.items[1].metadata.items[0].value);
    try testing.expectEqualStrings("42", ps.payloads.items[1].data);
    try testing.expectEqual(@as(usize, 0), (try decode(common.Payloads, arena.allocator(), "{}")).payloads.items.len);
}

test "decode accepts enums by full name, short name and number" {
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const history = proto.temporal.api.history.v1;
    const enums = proto.temporal.api.enums.v1;
    const h = try decode(history.History, a,
        \\{"events":[
        \\ {"eventId":"1","eventType":"WorkflowExecutionStarted","workflowExecutionStartedEventAttributes":{"taskQueue":{"kind":"Normal"}}},
        \\ {"event_id":"2","event_type":"EVENT_TYPE_WORKFLOW_TASK_SCHEDULED"},
        \\ {"eventId":"3","eventType":7},
        \\ {"eventId":"4","eventType":"workflow_task_completed"},
        \\ {"eventId":"5","eventType":"NoSuchEvent"},
        \\ {"eventId":"6","eventType":"event_type_workflow_task_started"}
        \\]}
    );
    const events = h.events.items;
    try testing.expectEqual(enums.EventType.EVENT_TYPE_WORKFLOW_EXECUTION_STARTED, events[0].event_type);
    try testing.expectEqual(enums.TaskQueueKind.TASK_QUEUE_KIND_NORMAL, events[0].attributes.?.workflow_execution_started_event_attributes.task_queue.?.kind);
    try testing.expectEqual(enums.EventType.EVENT_TYPE_WORKFLOW_TASK_SCHEDULED, events[1].event_type);
    try testing.expectEqual(@as(i64, 2), events[1].event_id);
    try testing.expectEqual(@as(enums.EventType, @fromBackingInt(@intCast(7))), events[2].event_type);
    try testing.expectEqual(enums.EventType.EVENT_TYPE_WORKFLOW_TASK_COMPLETED, events[3].event_type);
    try testing.expectEqual(enums.EventType.EVENT_TYPE_UNSPECIFIED, events[4].event_type);
    try testing.expectEqual(enums.EventType.EVENT_TYPE_WORKFLOW_TASK_STARTED, events[5].event_type);
}

test "short enum names decode in repeated fields, map values and nested messages" {
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const enums = proto.temporal.api.enums.v1;
    // A repeated enum: ResetWorkflowExecutionRequest.reset_reapply_exclude_types.
    const req = try decode(proto.temporal.api.workflowservice.v1.ResetWorkflowExecutionRequest, a,
        \\{"resetReapplyExcludeTypes":["Signal","RESET_REAPPLY_EXCLUDE_TYPE_UPDATE"]}
    );
    try testing.expectEqualSlices(enums.ResetReapplyExcludeType, &.{
        .RESET_REAPPLY_EXCLUDE_TYPE_SIGNAL,
        .RESET_REAPPLY_EXCLUDE_TYPE_UPDATE,
    }, req.reset_reapply_exclude_types.items);

    // A pointer-held message inside a oneof member: a failure's cause.
    const f = try decode(proto.temporal.api.failure.v1.Failure, a,
        \\{"cause":{"timeoutFailureInfo":{"timeoutType":"StartToClose"}}}
    );
    try testing.expectEqual(enums.TimeoutType.TIMEOUT_TYPE_START_TO_CLOSE, f.cause.?.failure_info.?.timeout_failure_info.timeout_type);
}

test "decode rejects JSON nested deeper than it can write back" {
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const depth = 10_000;
    var text: std.ArrayList(u8) = .empty;
    try text.appendSlice(a, "{\"events\":");
    try text.appendNTimes(a, '[', depth);
    try text.appendNTimes(a, ']', depth);
    try text.append(a, '}');
    try testing.expectError(error.InvalidProtoJson, decode(proto.temporal.api.history.v1.History, a, text.items));
}

test "encode output decodes to an equal History" {
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const json =
        \\{"events":[{"eventId":"1","eventTime":"2020-07-30T00:30:03.082421843Z","eventType":"EVENT_TYPE_WORKFLOW_EXECUTION_STARTED","workflowExecutionStartedEventAttributes":{"workflowType":{"name":"W"},"taskQueue":{"name":"q","kind":"TASK_QUEUE_KIND_NORMAL"},"input":{"payloads":[{"metadata":{"encoding":"YmluYXJ5L3BsYWlu","k":"//79"},"data":"AP8="}]},"workflowRunTimeout":"60s"}}]}
    ;
    const h = try decode(proto.temporal.api.history.v1.History, a, json);
    try testing.expectEqualStrings(json, try encode(a, h));
}

/// As protoc-gen-zig generates `message Cart { repeated string items = 1; int32 capacity = 2;
/// map<string, bytes> labels = 3; TaskQueueKind kind = 4; }` for an application: a message
/// whose fields happen to be named `items` and `capacity`, like a `std.ArrayList`'s.
const Cart = struct {
    items: std.ArrayList([]const u8) = .empty,
    capacity: i32 = 0,
    labels: std.ArrayList(LabelsEntry) = .empty,
    kind: proto.temporal.api.enums.v1.TaskQueueKind = @fromBackingInt(0),
    _unknown_fields: []const u8 = &.{},

    pub const _desc_table = .{
        .items = protobuf.fdf(1, .{ .repeated = .{ .scalar = .string } }, .{ .utf8_validation = .verify }),
        .capacity = protobuf.fd(2, .{ .scalar = .int32 }),
        .labels = protobuf.fd(3, .{ .repeated = .submessage }),
        .kind = protobuf.fd(4, .@"enum"),
    };

    pub const LabelsEntry = struct {
        key: []const u8 = &.{},
        value: []const u8 = &.{},

        pub const _desc_table = .{
            .key = protobuf.fdf(1, .{ .scalar = .string }, .{ .utf8_validation = .verify }),
            .value = protobuf.fd(2, .{ .scalar = .bytes }),
        };
    };

    pub fn jsonDecode(input: []const u8, options: std.json.ParseOptions, allocator: Allocator) !std.json.Parsed(@This()) {
        return protobuf.json.decode(@This(), input, options, allocator);
    }

    pub fn jsonParse(allocator: Allocator, source: anytype, options: std.json.ParseOptions) !@This() {
        return protobuf.json.parse(@This(), allocator, source, options);
    }
};

test "a message with fields named items and capacity decodes" {
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const cart = try decode(Cart, a,
        \\{"items":["book"],"capacity":3,"labels":{"raw":"//79"},"kind":"Sticky"}
    );
    try testing.expectEqualStrings("book", cart.items.items[0]);
    try testing.expectEqual(@as(i32, 3), cart.capacity);
    try testing.expectEqualSlices(u8, &.{ 0xff, 0xfe, 0xfd }, cart.labels.items[0].value);
    try testing.expectEqual(proto.temporal.api.enums.v1.TaskQueueKind.TASK_QUEUE_KIND_STICKY, cart.kind);
}

/// As protoc-gen-zig generates `message Secret { string key = 1; bytes value = 2; }` and
/// `message Envelope { Secret secret = 1; }` without
/// `preserve_unknown_fields`, its default: `Secret` has exactly the fields `key` and `value`,
/// like a map entry, but is an ordinary message.
const Envelope = struct {
    secret: ?Secret = null,

    pub const _desc_table = .{
        .secret = protobuf.fd(1, .submessage),
    };

    pub const Secret = struct {
        key: []const u8 = &.{},
        value: []const u8 = &.{},

        pub const _desc_table = .{
            .key = protobuf.fdf(1, .{ .scalar = .string }, .{ .utf8_validation = .verify }),
            .value = protobuf.fd(2, .{ .scalar = .bytes }),
        };

        pub fn jsonDecode(input: []const u8, options: std.json.ParseOptions, allocator: Allocator) !std.json.Parsed(@This()) {
            return protobuf.json.decode(@This(), input, options, allocator);
        }

        pub fn jsonParse(allocator: Allocator, source: anytype, options: std.json.ParseOptions) !@This() {
            return protobuf.json.parse(@This(), allocator, source, options);
        }
    };

    pub fn jsonDecode(input: []const u8, options: std.json.ParseOptions, allocator: Allocator) !std.json.Parsed(@This()) {
        return protobuf.json.decode(@This(), input, options, allocator);
    }

    pub fn jsonParse(allocator: Allocator, source: anytype, options: std.json.ParseOptions) !@This() {
        return protobuf.json.parse(@This(), allocator, source, options);
    }
};

test "a message with fields named key and value decodes its bytes once" {
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    // "abcd" is "YWJjZA==" in base64, and is itself valid base64 of three other bytes.
    const json = try encode(a, Envelope{ .secret = .{ .key = "k", .value = "abcd" } });
    try testing.expectEqualStrings(
        \\{"secret":{"key":"k","value":"YWJjZA=="}}
    , json);
    const back = try decode(Envelope, a, json);
    try testing.expectEqualStrings("abcd", back.secret.?.value);
    try testing.expectEqualStrings("k", (try decode(Envelope.Secret, a,
        \\{"key":"k","value":"YWJjZA=="}
    )).key);
    try testing.expectEqualStrings("abcd", (try decode(Envelope.Secret, a,
        \\{"key":"k","value":"YWJjZA=="}
    )).value);
}

/// A message that holds `Envelope.Secret` (exactly `key` and `value` fields) in a repeated
/// field, which zig-protobuf's `json.zig` reads and writes as a JSON object like a map, and as
/// the value of a `map<string, Secret>`, where it is an ordinary message.
const Vault = struct {
    secrets: std.ArrayList(Envelope.Secret) = .empty,
    by_name: std.ArrayList(ByNameEntry) = .empty,

    pub const _desc_table = .{
        .secrets = protobuf.fd(1, .{ .repeated = .submessage }),
        .by_name = protobuf.fd(2, .{ .repeated = .submessage }),
    };

    pub const ByNameEntry = struct {
        key: []const u8 = &.{},
        value: ?Envelope.Secret = null,

        pub const _desc_table = .{
            .key = protobuf.fdf(1, .{ .scalar = .string }, .{ .utf8_validation = .verify }),
            .value = protobuf.fd(2, .submessage),
        };
    };

    pub fn jsonDecode(input: []const u8, options: std.json.ParseOptions, allocator: Allocator) !std.json.Parsed(@This()) {
        return protobuf.json.decode(@This(), input, options, allocator);
    }

    pub fn jsonParse(allocator: Allocator, source: anytype, options: std.json.ParseOptions) !@This() {
        return protobuf.json.parse(@This(), allocator, source, options);
    }
};

test "bytes are decoded once wherever a message with key and value fields sits" {
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();

    // A repeated field of it is read as a map, whose bytes values the generated decoder
    // leaves as base64 text; a map value of its type is read as a message, whose bytes it
    // decodes. Either way the bytes come back as they went in.
    var vault: Vault = .{};
    try vault.secrets.append(a, .{ .key = "k", .value = "abcd" });
    try vault.by_name.append(a, .{ .key = "n", .value = .{ .key = "inner", .value = "abcd" } });
    const back = try decode(Vault, a, try encode(a, vault));
    try testing.expectEqualStrings("k", back.secrets.items[0].key);
    try testing.expectEqualStrings("abcd", back.secrets.items[0].value);
    try testing.expectEqualStrings("inner", back.by_name.items[0].value.?.key);
    try testing.expectEqualStrings("abcd", back.by_name.items[0].value.?.value);

    // A generated map entry type decoded on its own is an ordinary message too.
    const entry = try decode(common.Payload.MetadataEntry, a,
        \\{"key":"encoding","value":"YWJjZA=="}
    );
    try testing.expectEqualStrings("abcd", entry.value);
}
